return [
  {
    json: {
      requirement:
        $input.first().json.requirement ||
        "Build an AI Invoice Approval Workflow"
    }
  }
];

return [
  {
    json: {
      requirement: $json.requirement,

      payload: {
        model: "models/gemini-embedding-001",

        content: {
          parts: [
            {
              text: $json.requirement
            }
          ]
        }
      }
    }
  }
];

const vector = $json.embedding?.values;

if (!vector || !Array.isArray(vector)) {
	throw new Error("Embedding vector not found.");
}

const requirement = $("Code (Build Gemini Embedding Payload)")
	.first()
	.json.requirement;

return [
	{
		json: {
			requirement,
			vector,
			vector_dimension: vector.length
		}
	}
];

// Validate Qdrant response
if (!$json.result || !Array.isArray($json.result) || $json.result.length === 0) {
	throw new Error("No workflows found in Qdrant.");
}


// Qdrant returns chunks: collapse to one row per workflow and borrow market data from any chunk that has it
const _all = $json.result || [];
const _market = {};
for (const r of _all) { const p = r.payload || {}; if (p.workflow_name && p.project_rate != null && !_market[p.workflow_name]) _market[p.workflow_name] = p; }
const _seen = new Set();
const _unique = _all.filter(r => { const n = (r.payload || {}).workflow_name || (r.payload || {}).project_name; if (!n || _seen.has(n)) return false; _seen.add(n); return true; })
  .map(r => ({ ...r, payload: { ..._market[(r.payload || {}).workflow_name], ...(r.payload || {}) , ...Object.fromEntries(Object.entries(_market[(r.payload || {}).workflow_name] || {}).filter(([k]) => ["project_rate","business_value","difficulty","estimated_hours","automation_level","market_reason","workflow_description","technologies","integrations","use_cases"].includes(k))) } }));

// Get requirement from previous node
const requirement = $("Code (Extract Embedding)1").item.json.requirement;


// Extract workflows
const workflows = _unique.slice(0, 5).map((item, index) => {

	const payload = item.payload || {};

	return {

		rank: index + 1,

		workflow_name:
			payload.workflow_name ||
			payload.project_name ||
			"",

		search_score:
			Number(item.score || 0),


		project_rate:
			payload.project_rate || 0,


		business_value:
			payload.business_value || 0,


		difficulty:
			payload.difficulty || "",


		estimated_hours:
			payload.estimated_hours || 0,


		automation_level:
			payload.automation_level || "",


		market_reason:
			payload.market_reason || "",


		workflow_description:
			payload.workflow_description || "",


		// FIXED CATEGORY
		workflow_category:
			payload.workflow_category ||
			payload.category ||
			payload.niche ||
			"Not Available",


		technologies:
			payload.technologies || "",


		integrations:
			payload.integrations || "",


		use_cases:
			payload.use_cases || ""

	};

});


// Best similarity score
const bestSearchScore =
	workflows.length > 0
		? workflows[0].search_score
		: 0;


// Confidence
const searchStatus =
	bestSearchScore >= 0.65
		? "High Confidence Match"
		: "Low Confidence Match";


// Final Output
return [
	{
		json: {

			requirement,

			best_search_score:
				bestSearchScore,


			search_status:
				searchStatus,


			total_matches:
				workflows.length,


			workflows

		}
	}
];

const responseText = 
$json.candidates?.[0]?.content?.parts?.[0]?.text;

if (!responseText) {
  throw new Error("Gemini response empty");
}


// Extract JSON between first { and last }
const start = responseText.indexOf("{");
const end = responseText.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error(
    "No JSON found in Gemini response:\n" + responseText
  );
}

const jsonString = responseText.substring(start, end + 1);


let analytics;

try {
  analytics = JSON.parse(jsonString);
}
catch(error){

  throw new Error(
    "JSON Parsing Failed:\n" + jsonString
  );

}


return [
 {
  json: analytics
 }
];

const prompt = $node["Code (Build Analytics Prompt)"].json.prompt;

return [
  {
    json: {
      contents: [
        {
          parts: [
            {
              text: prompt
            }
          ]
        }
      ]
    }
  }
];
